package dev.openallay.runtime.forge1122;
public final class CapabilityBridgeTest {
    public static void main(String[] args)throws Exception {
        byte[] raw=java.util.Base64.getDecoder().decode("");
        byte[] result=CapabilityBridge.patch(raw);
        org.objectweb.asm.tree.ClassNode node=new org.objectweb.asm.tree.ClassNode();new org.objectweb.asm.ClassReader(result).accept(node,0);
        int helpers=0,old=0;
        for(Object object:node.methods)for(org.objectweb.asm.tree.AbstractInsnNode i=((org.objectweb.asm.tree.MethodNode)object).instructions.getFirst();i!=null;i=i.getNext())
            if(i instanceof org.objectweb.asm.tree.MethodInsnNode){org.objectweb.asm.tree.MethodInsnNode m=(org.objectweb.asm.tree.MethodInsnNode)i;
                if(CapabilityBridge.HELPER.equals(m.owner)&&"setField".equals(m.name))helpers++;
                if("net/minecraftforge/common/util/EnumHelper".equals(m.owner))old++;}
        if(helpers!=1||old!=0)throw new AssertionError("One exact setter call required");
        raw[raw.length-1]^=1;
        try{CapabilityBridge.patch(raw);throw new AssertionError("Corrupt class accepted");}catch(IllegalStateException expected){}
        System.out.println("PASS genuine capability callback one-call redirect; mutated bytes rejected");
    }
}
